=== FILE: apb_regs.v ===
`timescale 1ns / 1ps
// apb_regs: four 32-bit read/write registers behind an APB4 completer port.
// Implements microarchitecture.md: zero wait states, no state machine,
// combinational read multiplexer, PSLVERR for unmapped addresses.
module apb_regs #(
  parameter integer ADDR_WIDTH = 8,
  parameter integer DATA_WIDTH = 32
) (
  input  wire                    pclk,
  input  wire                    presetn,
  input  wire [ADDR_WIDTH-1:0]   paddr,
  input  wire                    psel,
  input  wire                    penable,
  input  wire                    pwrite,
  input  wire [DATA_WIDTH-1:0]   pwdata,
  input  wire [DATA_WIDTH/8-1:0] pstrb,
  output reg  [DATA_WIDTH-1:0]   prdata,
  output wire                    pready,
  output wire                    pslverr
);

  localparam integer NBYTES = DATA_WIDTH / 8;

  // Access phase: the one cycle in which the response is sampled and a
  // write takes effect (pready is always high).
  wire access = psel && penable;

  // Mapped: word aligned and inside 0x0..0xC.
  wire mapped = (paddr[1:0] == 2'b00) &&
                (paddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});

  wire [1:0] idx   = paddr[3:2];
  wire       wr_en = access && pwrite && mapped;
  wire       rd_en = access && !pwrite && mapped;

  // Byte-lane mask from the strobes: lane n is bits 8n+7:8n.
  wire [DATA_WIDTH-1:0] bmask;
  genvar g;
  generate
    for (g = 0; g < NBYTES; g = g + 1) begin : g_mask
      assign bmask[g*8 +: 8] = {8{pstrb[g]}};
    end
  endgenerate

  assign pready  = 1'b1;
  assign pslverr = access && !mapped;

  // Register state.
  reg [DATA_WIDTH-1:0] reg0_q, reg1_q, reg2_q, reg3_q;
  reg [DATA_WIDTH-1:0] reg0_d, reg1_d, reg2_d, reg3_d;

  // Next state: hold, or merge the strobed bytes of pwdata into the
  // addressed register on a mapped write access.
  always @* begin
    reg0_d = reg0_q;
    reg1_d = reg1_q;
    reg2_d = reg2_q;
    reg3_d = reg3_q;
    if (wr_en) begin
      case (idx)
        2'd0:    reg0_d = (reg0_q & ~bmask) | (pwdata & bmask);
        2'd1:    reg1_d = (reg1_q & ~bmask) | (pwdata & bmask);
        2'd2:    reg2_d = (reg2_q & ~bmask) | (pwdata & bmask);
        2'd3:    reg3_d = (reg3_q & ~bmask) | (pwdata & bmask);
        default: begin end
      endcase
    end
  end

  // Synchronous, active-low reset.
  always @(posedge pclk) begin
    if (!presetn) begin
      reg0_q <= {DATA_WIDTH{1'b0}};
      reg1_q <= {DATA_WIDTH{1'b0}};
      reg2_q <= {DATA_WIDTH{1'b0}};
      reg3_q <= {DATA_WIDTH{1'b0}};
    end else begin
      reg0_q <= reg0_d;
      reg1_q <= reg1_d;
      reg2_q <= reg2_d;
      reg3_q <= reg3_d;
    end
  end

  // Read data: zero unless this is a mapped read access.
  always @* begin
    prdata = {DATA_WIDTH{1'b0}};
    if (rd_en) begin
      case (idx)
        2'd0:    prdata = reg0_q;
        2'd1:    prdata = reg1_q;
        2'd2:    prdata = reg2_q;
        2'd3:    prdata = reg3_q;
        default: prdata = {DATA_WIDTH{1'b0}};
      endcase
    end
  end

`ifdef FORMAL
  // Design-intent assertions (not proven by this delivery).
  reg f_past_valid;
  initial f_past_valid = 1'b0;
  always @(posedge pclk) f_past_valid <= 1'b1;

  always @(*) begin
    if (!f_past_valid) assume (!presetn);
    if (!presetn) assume (!psel);
  end

  always @(*) begin
    assert (pready);
    if (!access) begin
      assert (prdata == {DATA_WIDTH{1'b0}});
      assert (!pslverr);
    end
    if (access && !mapped) begin
      assert (pslverr);
      assert (prdata == {DATA_WIDTH{1'b0}});
    end
    if (access && mapped) assert (!pslverr);
  end

  always @(posedge pclk) begin
    if (f_past_valid && !$past(presetn)) begin
      assert (reg0_q == {DATA_WIDTH{1'b0}});
      assert (reg1_q == {DATA_WIDTH{1'b0}});
      assert (reg2_q == {DATA_WIDTH{1'b0}});
      assert (reg3_q == {DATA_WIDTH{1'b0}});
    end
    if (f_past_valid && $past(presetn) && !$past(wr_en)) begin
      assert (reg0_q == $past(reg0_q));
      assert (reg1_q == $past(reg1_q));
      assert (reg2_q == $past(reg2_q));
      assert (reg3_q == $past(reg3_q));
    end
  end
`endif

endmodule
=== END FILE ===
=== FILE: apb_regs_tb.v ===
`timescale 1ns / 1ps
// apb_regs_tb: directed self-checking testbench for apb_regs.
// Inputs change 0 ns after the falling edge; outputs are sampled 1 ns later,
// well before the rising edge. Expected values come from an independent
// model in this file.

`define CHECK(cond, msg) \
  begin \
    if (cond) passed = passed + 1; \
    else begin \
      failed = failed + 1; \
      $error("FAIL t=%0t addr=0x%02h: %s", $time, cur_addr, msg); \
    end \
  end

module apb_regs_tb;

  reg         pclk = 1'b0;
  reg         presetn;
  reg  [7:0]  paddr;
  reg         psel;
  reg         penable;
  reg         pwrite;
  reg  [31:0] pwdata;
  reg  [3:0]  pstrb;
  wire [31:0] prdata;
  wire        pready;
  wire        pslverr;

  integer        passed;
  integer        failed;
  integer        got;
  reg [8*64-1:0] nonce;
  reg [7:0]      cur_addr;
  reg [31:0]     model [0:3];
  reg [7:0]      a;
  reg [8:0]      ai;
  reg [4:0]      s;
  reg [31:0]     d;

  apb_regs #(.ADDR_WIDTH(8), .DATA_WIDTH(32)) dut (
    .pclk    (pclk),
    .presetn (presetn),
    .paddr   (paddr),
    .psel    (psel),
    .penable (penable),
    .pwrite  (pwrite),
    .pwdata  (pwdata),
    .pstrb   (pstrb),
    .prdata  (prdata),
    .pready  (pready),
    .pslverr (pslverr)
  );

  always #5 pclk = ~pclk;

  // Independent decode: word aligned and below 0x10.
  function tb_mapped;
    input [7:0] addr;
    begin
      tb_mapped = (addr[1:0] == 2'b00) && (addr < 8'h10);
    end
  endfunction

  // Independent byte merge.
  function [31:0] tb_merge;
    input [31:0] old_v;
    input [31:0] data;
    input [3:0]  strb;
    begin
      tb_merge = { (strb[3] ? data[31:24] : old_v[31:24]),
                   (strb[2] ? data[23:16] : old_v[23:16]),
                   (strb[1] ? data[15:8]  : old_v[15:8]),
                   (strb[0] ? data[7:0]   : old_v[7:0]) };
    end
  endfunction

  task reset_model;
    begin
      model[0] = 32'h0000_0000;
      model[1] = 32'h0000_0000;
      model[2] = 32'h0000_0000;
      model[3] = 32'h0000_0000;
    end
  endtask

  // Checks for any cycle outside the access phase.
  task check_quiet;
    begin
      `CHECK(prdata === 32'h0000_0000, "prdata not zero outside access phase")
      `CHECK(pslverr === 1'b0, "pslverr not zero outside access phase")
      `CHECK(pready === 1'b1, "pready not high")
    end
  endtask

  // One APB transfer: setup cycle, then one access cycle.
  task apb_xfer;
    input        wr;
    input [7:0]  addr;
    input [31:0] wdata;
    input [3:0]  strb;
    input        exp_err;
    input [31:0] exp_rdata;
    begin
      cur_addr = addr;
      // Setup phase.
      @(negedge pclk);
      psel    = 1'b1;
      penable = 1'b0;
      pwrite  = wr;
      paddr   = addr;
      pwdata  = wdata;
      pstrb   = wr ? strb : 4'b0000;
      #1;
      check_quiet;
      // Access phase.
      @(negedge pclk);
      penable = 1'b1;
      #1;
      `CHECK(pready === 1'b1, "wait state: pready low in access phase")
      `CHECK(pslverr === exp_err, "pslverr does not match address policy")
      if (wr) begin
        `CHECK(prdata === 32'h0000_0000, "prdata not zero in write access")
      end else begin
        `CHECK(prdata === exp_rdata, "read data mismatch")
      end
    end
  endtask

  task do_write;
    input [7:0]  addr;
    input [31:0] wdata;
    input [3:0]  strb;
    reg m;
    begin
      m = tb_mapped(addr);
      apb_xfer(1'b1, addr, wdata, strb, ~m, 32'h0000_0000);
      if (m) model[addr[3:2]] = tb_merge(model[addr[3:2]], wdata, strb);
    end
  endtask

  task do_read;
    input [7:0] addr;
    reg m;
    begin
      m = tb_mapped(addr);
      apb_xfer(1'b0, addr, 32'hBAD0_BAD0, 4'b0000, ~m,
               m ? model[addr[3:2]] : 32'h0000_0000);
    end
  endtask

  // Back-to-back reads of all four registers.
  task read_all;
    begin
      do_read(8'h00);
      do_read(8'h04);
      do_read(8'h08);
      do_read(8'h0C);
    end
  endtask

  // Idle cycles with an unselected write pattern on the bus.
  task idle;
    input integer n;
    integer j;
    begin
      for (j = 0; j < n; j = j + 1) begin
        @(negedge pclk);
        cur_addr = 8'h04;
        psel     = 1'b0;
        penable  = 1'b0;
        pwrite   = 1'b1;
        paddr    = 8'h04;
        pwdata   = 32'hFFFF_FFFF;
        pstrb    = 4'hF;
        #1;
        check_quiet;
      end
    end
  endtask

  initial begin
    passed = 0;
    failed = 0;
    nonce  = {(8*64){1'b0}};
    got    = $value$plusargs("nirmaan_nonce=%s", nonce);
    reset_model;
    cur_addr = 8'h00;
    presetn  = 1'b0;
    psel     = 1'b0;
    penable  = 1'b0;
    pwrite   = 1'b0;
    paddr    = 8'h00;
    pwdata   = 32'h0000_0000;
    pstrb    = 4'h0;

    // Reset: outputs quiet, pready high.
    repeat (3) begin
      @(negedge pclk);
      #1;
      check_quiet;
    end
    @(negedge pclk);
    presetn = 1'b1;
    idle(2);

    // Reset values.
    read_all;
    idle(1);

    // Full writes with idle gaps, then back-to-back readback.
    do_write(8'h00, 32'h1234_5678, 4'hF);
    idle(1);
    do_write(8'h04, 32'h9ABC_DEF0, 4'hF);
    idle(2);
    do_write(8'h08, 32'h0F1E_2D3C, 4'hF);
    idle(1);
    do_write(8'h0C, 32'h4B5A_6978, 4'hF);
    idle(1);
    read_all;

    // Back-to-back writes of distinct patterns, back-to-back reads.
    for (a = 8'h00; a < 8'h10; a = a + 8'h04) begin
      d = {a, ~a, a ^ 8'h5A, 8'hC3};
      do_write(a, d, 4'hF);
    end
    read_all;

    // Every bit to one, then to zero.
    for (a = 8'h00; a < 8'h10; a = a + 8'h04) do_write(a, 32'hFFFF_FFFF, 4'hF);
    read_all;
    for (a = 8'h00; a < 8'h10; a = a + 8'h04) do_write(a, 32'h0000_0000, 4'hF);
    read_all;
    idle(1);

    // Write then read the same register back to back.
    do_write(8'h04, 32'hCAFE_F00D, 4'hF);
    do_read(8'h04);

    // All 16 strobe patterns on REG2, including none.
    do_write(8'h08, 32'hDEAD_BEEF, 4'hF);
    for (s = 5'd0; s < 5'd16; s = s + 5'd1) begin
      d = {3'b000, s, 3'b001, s, 3'b010, s, 3'b011, s};
      do_write(8'h08, d, s[3:0]);
      do_read(8'h08);
    end

    // Partial strobes on the other registers.
    do_write(8'h00, 32'hA1B2_C3D4, 4'b0101);
    do_write(8'h04, 32'hE5F6_0718, 4'b1010);
    do_write(8'h0C, 32'h2939_4A5B, 4'b0001);
    do_write(8'h0C, 32'h6C7D_8E9F, 4'b1000);
    do_write(8'h00, 32'h0000_0000, 4'b0000);
    read_all;
    idle(1);

    // Make every register nonzero before the address sweep.
    do_write(8'h00, 32'h1111_1111, 4'hF);
    do_write(8'h04, 32'h2222_2222, 4'hF);
    do_write(8'h08, 32'h3333_3333, 4'hF);
    do_write(8'h0C, 32'h4444_4444, 4'hF);

    // Exhaustive address sweep: PSLVERR policy for every address, and no
    // aliasing write into the register at the same index.
    for (ai = 9'd0; ai < 9'd256; ai = ai + 9'd1) begin
      a = ai[7:0];
      do_write(a, ~{a, a, a, a}, 4'hF);
      do_read(a);
      do_read(a & 8'h0C);
      if (ai[3:0] == 4'hF) idle(1);
    end

    // Unmapped writes with partial strobes.
    do_write(8'h11, 32'h5555_5555, 4'b0011);
    do_write(8'h06, 32'h6666_6666, 4'b1100);
    do_write(8'hFC, 32'h7777_7777, 4'b0001);
    read_all;

    // Reset again: make all registers nonzero, reset, check zero.
    do_write(8'h00, 32'h8888_8888, 4'hF);
    do_write(8'h04, 32'h9999_9999, 4'hF);
    do_write(8'h08, 32'hAAAA_AAAA, 4'hF);
    do_write(8'h0C, 32'hBBBB_BBBB, 4'hF);
    read_all;
    idle(1);
    @(negedge pclk);
    psel    = 1'b0;
    penable = 1'b0;
    presetn = 1'b0;
    #1;
    check_quiet;
    repeat (2) begin
      @(negedge pclk);
      #1;
      check_quiet;
    end
    @(negedge pclk);
    presetn = 1'b1;
    reset_model;
    idle(1);
    read_all;
    idle(2);

    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

endmodule
=== END FILE ===
